gPt(){return"\u0631\u06ce\u06a9\u062e\u0633\u062a\u0646\u06ce\u0646 \u0647\u06d5\u0645\u06cc \u0644\u0642\u06cc \u0648 \u062d\u06d5\u0632\u06ce\u0646 \u062a\u06d5 \u06cc\u06ce\u0646 \u062a\u0627\u06cc\u0628\u06d5\u062a."},
gNt(){return"\u0631\u06ce\u06a9\u062e\u0633\u062a\u0646\u06ce\u0646 \u0644\u0642\u06cc"},
gOI(){return"\u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u0627 \u0626\u06c6\u0646\u0644\u0627\u06cc\u0646"},
gOJ(){return"\u0628\u0647\u06ce\u0644\u06d5 \u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u0631\u0627\u0633\u062a\u06d5\u0648\u062e\u06c6 \u0628 \u0631\u06ce\u06cc\u0627 \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06d5\u06a9\u06ce \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06ce \u067e\u0627\u0631\u06d5\u06cc\u06ce \u0628\u062f\u06d5\u0646\u06d5 \u062a\u06d5. \u0647\u06d5\u0631 \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06d5\u06a9 \u067e\u06ce\u062f\u06a4\u06cc \u0628 \u0647\u06d5\u0698\u0645\u0627\u0631\u0627 \u0628\u0627\u0632\u0631\u06af\u0627\u0646\u06cc \u06cc\u0627 \u062e\u06c6 \u0647\u06d5\u06cc\u06d5\u060c \u06a9\u0648 \u0628 \u062c\u0648\u062f\u0627 \u062f\u06af\u06d5\u0644 \u0648\u06cc \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06cc \u062f\u0647\u06ce\u062a\u06d5 \u062f\u0627\u0646\u0627\u0646."},
gO6(){return"\u0686\u0627\u0644\u0627\u06a9\u06d5"},
gO9(){return"\u0631\u06ce\u06a9 \u0646\u06d5\u0647\u0627\u062a\u06cc\u06d5 \u062e\u0633\u062a\u0646"},
