gO3(){return"\u0631\u06ce\u06a9\u062e\u0633\u062a\u0646"},
O5(a){return"\u0631\u06ce\u06a9\u062e\u0633\u062a\u0646\u0627 "+a},
gO7(){return"\u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u0627\u0646 \u0628 \u0631\u06ce\u06cc\u0627 \u06a4\u06cc \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06cc \u0648\u06d5\u0631\u06af\u0631\u06d5"},
gO4(){return"\u06a4\u0627\u0644\u0627 \u0628\u0647\u06ce\u0644\u06d5 \u0628\u06c6 \u0647\u06ce\u0644\u0627\u0646\u0627 \u0646\u0631\u062e\u06ce \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a\u06a9\u0631\u06cc"},
gOb(){return"\u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06ce \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u06ce \u0647\u0627\u062a\u06d5 \u0646\u0648\u0648\u06a9\u0631\u0646."},
Oa(a){return"\u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a\u06a9\u0631\u0646 \u0633\u06d5\u0631\u0646\u06d5\u06a9\u06d5\u0641\u062a: "+a},
gO8(){return"\u0647\u06d5\u0631 \u0633\u06ce \u062e\u0627\u0646\u0627\u0646 \u067e\u0695 \u0628\u06a9\u06d5\u060c \u06cc\u0627\u0646 \u0647\u06d5\u0631 \u0633\u06ce\u06cc\u0627\u0646 \u06a4\u0627\u0644\u0627 \u0628\u0647\u06ce\u0644\u06d5 \u0628\u06c6 \u0647\u06ce\u0644\u0627\u0646\u0627 \u0646\u0631\u062e\u06ce \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a\u06a9\u0631\u06cc."},
gPJ(){return"\u0698\u0645\u0627\u0631\u0627 \u062c\u0632\u062f\u0627\u0646\u06ce (msisdn)"},
