gPK(){return"\u06a9\u0644\u06cc\u0644\u0627 \u0646\u0647\u06ce\u0646\u06cc (Secret)"},
gPL(){return"\u062f\u06c6\u062e\u06ce \u062a\u0627\u0642\u06cc\u06a9\u0631\u0646\u06ce (sandbox)"},
gOX(){return"\u0646\u0627\u06a4\u06ce \u0628\u06a9\u0627\u0631\u0647\u06ce\u0646\u06d5\u0631\u06cc"},
gOV(){return"\u067e\u06d5\u06cc\u06a4\u0627 \u0646\u0647\u06ce\u0646\u06cc"},
gOW(){return"\u0646\u0627\u0633\u0646\u0627\u0645\u0627 \u062a\u06ce\u0631\u0645\u06cc\u0646\u0627\u0644\u06ce (Terminal ID)"},
gNY(){return"\u0646\u0627\u0633\u0646\u0627\u0645\u0627 \u06a9\u0695\u06cc\u0627\u0631\u06cc (Client ID)"},
