gOs(){return"\u06a9\u0644\u06cc\u0644\u0627 \u0646\u0647\u06ce\u0646\u06cc"},
gOH(){return"\u0647\u06ce\u0634\u062a\u0627 \u0686 \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06ce \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u0627 \u0626\u06c6\u0646\u0644\u0627\u06cc\u0646 \u0628\u06c6 \u0648\u06d5\u0644\u0627\u062a\u06ce \u062a\u06d5 \u0628\u06d5\u0631\u062f\u06d5\u0633\u062a \u0646\u06cc\u0646\u06d5. \u0626\u06d5\u06af\u06d5\u0631 \u062a\u06d5 \u062f\u06a4\u06ce\u062a \u0626\u06ce\u06a9 \u0628\u0647\u06ce\u062a\u06d5 \u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06ce \u0628 \u0645\u06d5 \u0628\u06a9\u06d5."},
gO1(){return"\u0646\u0627\u06a4\u0646\u06cc\u0634\u0627\u0646\u06ce \u0633\u06d5\u0631\u06d5\u06a9\u06cc \u06cc\u06ce \u0628\u06d5\u0631\u0647\u06d5\u0645\u06ce (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5)"},
gO0(){return"\u06a4\u0627\u0644\u0627 \u0628\u0647\u06ce\u0644\u06d5 \u0628\u06c6 \u0628\u06a9\u0627\u0631\u0626\u06cc\u0646\u0627\u0646\u0627 \u0646\u0627\u06a4\u0646\u06cc\u0634\u0627\u0646\u06ce \u062a\u0627\u0642\u06cc\u06a9\u0631\u0646\u06ce (sandbox). \u0626\u06d5\u06a4 \u062f\u0627\u0628\u06cc\u0646\u06a9\u06d5\u0631\u06d5 \u0646\u0627\u06a4\u0646\u06cc\u0634\u0627\u0646\u06ce \u062e\u06c6 \u06cc\u06ce \u0628\u06d5\u0631\u0647\u06d5\u0645\u06ce \u0628 \u0626\u0627\u0634\u06a9\u06d5\u0631\u0627\u06cc\u06cc \u0628\u06d5\u0644\u0627\u06a4 \u0646\u0627\u06a9\u06d5\u062a \u2014 \u067e\u0634\u062a\u06cc \u0647\u06d5\u0698\u0645\u0627\u0631\u0627 \u062a\u06d5 \u0647\u0627\u062a\u06d5 \u067e\u06d5\u0633\u06d5\u0646\u062f\u06a9\u0631\u0646 \u0631\u0627\u0633\u062a\u06d5\u0648\u062e\u06c6 \u0698 \u0648\u0627\u0646 \u0648\u06d5\u0631\u06af\u0631\u06d5."},
gOM(){return"\u062d\u06d5\u0632\u06ce\u0646 \u0645\u0646"},
gOT(){return"\u0686\u0627\u067e\u06a9\u0631\u0646"},
gOU(){return"\u0628\u06d5\u0644\u06af\u06d5\u0646\u0627\u0645\u06d5\u06cc\u06ce\u0646 \u0686\u0627\u067e\u06a9\u0631\u06cc \u0628\u06c6 \u06a4\u06cc \u0644\u0642\u06cc \u0686\u0627\u0648\u0627 \u062f\u06cc\u0627\u0631 \u062f\u0628\u0646."},
gOz(){return"\u062c\u0647\u06ce \u0644\u06c6\u06af\u06c6\u06cc"},
